//! M7 network identity: the game's ENTIRE live-service configuration
//! (gate keys, gate addresses, server list) is read from
//! `Network/conf.json` inside `LuaScripts.xdf` (a plain ZIP the Lua layer
//! streams through SharpZipLib). Whoever supplies that file owns the
//! client. Two tamper-safe mechanisms (IAT pointer swaps only):
//!
//! 1. **XDF redirect**: `CreateFileW` detour — any open of the game's
//!    LuaScripts.xdf is redirected to `AniiModLoader/Serviimo/LuaScripts.xdf`
//!    when that file exists (generated by Serviimo's `tools/xdfconf.py`
//!    from the user's AniiSignal.json: Serviimo keys + gate + Servers[]).
//! 2. **Vanilla DNS block**: `getaddrinfo`/`GetAddrInfoW` detours refuse
//!    resolution for configured domain suffixes (the vanilla live-service
//!    hosts) — belt & suspenders on top of the config itself.
//!
//! Config: `AniiModLoader/network.json`
//!   {"redirectXdf": "AniiModLoader/Serviimo/LuaScripts.xdf",
//!    "blockedDomains": ["kingsgroupgames.com"]}

use std::os::windows::ffi::OsStrExt;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::OnceLock;

#[link(name = "kernel32")]
extern "system" {
    fn GetFileAttributesW(name: *const u16) -> u32;
}

pub struct NetConfig {
    pub redirect_xdf: Option<String>,
    pub blocked_domains: Vec<String>,
}

/// M10 alt-save isolation — MOD-OWNED, per user direction: the feature
/// lives with the AniiSignal mod, never with the loader. The detour can
/// only exist here (it's the process-wide CreateFileW hook), but it is
/// ARMED solely by the mod's own config: `Mods/AniiSignal.json`. No mod
/// config → no remap → the vanilla LocalLow tree is used untouched even
/// under the modloader. `"ProfileKey": "<steamid64>"` in that config
/// names the alt-save directory (Steam-ID paired, Elden-Ring-alt-save
/// style); absent key → "default".
static PROFILE_KEY: OnceLock<Option<String>> = OnceLock::new();

fn profile_key() -> Option<&'static str> {
    PROFILE_KEY
        .get_or_init(|| {
            let mut path = crate::sys::exe_dir();
            path.push("Mods");
            path.push("AniiSignal.json");
            // Mod config missing → feature fully off (vanilla paths).
            let text = std::fs::read_to_string(&path).ok()?;
            const KEY: &str = "\"ProfileKey\"";
            let key = text.find(KEY).and_then(|kpos| {
                let rest = &text[kpos + KEY.len()..];
                let q = rest.find('"')?;
                let after = &rest[q + 1..];
                let e = after.find('"')?;
                Some(after[..e].to_string())
            });
            Some(key.unwrap_or_else(|| "default".to_string()))
        })
        .as_deref()
}

static CONFIG: OnceLock<NetConfig> = OnceLock::new();
/// per-label redirect counters: [xdf, xdt, fpx_config, fpx_md5sums, profile]
static REDIRECT_HITS_PER: [AtomicUsize; 5] = [AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0)];
static BLOCK_HITS: AtomicUsize = AtomicUsize::new(0);

pub fn init(cfg: NetConfig) {
    let _ = CONFIG.set(cfg);
}

pub fn config() -> Option<&'static NetConfig> {
    CONFIG.get()
}

fn log(line: &str) {
    crate::log_line(line);
}

/// True when the wide path ends with `suffix` (both lowercased ASCII).
fn wide_ends_with(path: &[u16], suffix_lower: &[u8]) -> bool {
    if path.len() < suffix_lower.len() {
        return false;
    }
    let start = path.len() - suffix_lower.len();
    for (i, &w) in path[start..].iter().enumerate() {
        let c = (w & 0xFF) as u8; // ASCII path chars only; non-ASCII can't match
        if c.to_ascii_lowercase() != suffix_lower[i] {
            return false;
        }
    }
    true
}

/// Case-insensitive ASCII substring search; returns the index in `path`
/// where `needle_lower` starts. Profile paths from Unity are ASCII.
fn wide_find_ci(path: &[u16], needle_lower: &[u8]) -> Option<usize> {
    if path.len() < needle_lower.len() {
        return None;
    }
    'outer: for start in 0..=path.len() - needle_lower.len() {
        for (i, &b) in needle_lower.iter().enumerate() {
            let c = (path[start + i] & 0xFF) as u8;
            if c.to_ascii_lowercase() != b {
                continue 'outer;
            }
        }
        return Some(start);
    }
    None
}

/// The vanilla persistent-data marker `\appdata\locallow\aniimo\aniimo\`
/// (case-insensitive, ASCII). Returns the byte index just past it, i.e.
/// the start of the per-user tail (`client_cache\...`, `Player.log`, …).
fn local_low_tail_start(path: &[u16]) -> Option<usize> {
    const MARKER: &[u8] = b"\\appdata\\locallow\\aniimo\\aniimo\\";
    let at = wide_find_ci(path, MARKER)?;
    Some(at + MARKER.len())
}

/// CreateFileW detour: redirect Serviimo-owned file opens. All are
/// existence-gated — a missing substitute must never reach the game
/// (missing-XDF aborts the Lua bootstrap with an int3 assert).
pub unsafe extern "system" fn create_file_w_detour(
    filename: *const u16,
    desired_access: u32,
    share_mode: u32,
    security: *mut core::ffi::c_void,
    creation_disposition: u32,
    flags: u32,
    template: isize,
) -> isize {
    let real = match crate::events::real_create_file_w() {
        Some(r) => r,
        None => return -1,
    };
    match open_with_redirects(filename, desired_access, share_mode, security, creation_disposition, flags, template) {
        Some(handle) => handle,
        None => real(filename, desired_access, share_mode, security, creation_disposition, flags, template),
    }
}

/// CreateFileA detour (FPX.dll imports BOTH forms by ordinal — the config
/// read came through the ANSI one, live 2026-09-28: the rewritten config
/// never armed). Converts to wide and shares the W path logic.
pub unsafe extern "system" fn create_file_a_detour(
    filename: *const u8,
    desired_access: u32,
    share_mode: u32,
    security: *mut core::ffi::c_void,
    creation_disposition: u32,
    flags: u32,
    template: isize,
) -> isize {
    #[link(name = "kernel32")]
    extern "system" {
        fn MultiByteToWideChar(code_page: u32, flags: u32, bytes: *const u8, cb: i32, wide: *mut u16, cch: i32) -> i32;
    }
    const CP_ACP: u32 = 0;
    let real_a = match crate::events::real_create_file_a() {
        Some(r) => r,
        None => return -1,
    };
    let passthrough = |file_a: *const u8| -> isize {
        real_a(file_a, desired_access, share_mode, security, creation_disposition, flags, template)
    };
    if filename.is_null() {
        return passthrough(filename);
    }
    let mut len = 0usize;
    while *filename.add(len) != 0 {
        len += 1;
    }
    let cap = MultiByteToWideChar(CP_ACP, 0, filename, (len + 1) as i32, core::ptr::null_mut(), 0);
    if cap <= 0 {
        return passthrough(filename);
    }
    let mut wide = Vec::<u16>::with_capacity(cap as usize);
    let written = MultiByteToWideChar(CP_ACP, 0, filename, (len + 1) as i32, wide.as_mut_ptr(), cap);
    if written <= 0 {
        return passthrough(filename);
    }
    wide.set_len(written as usize);
    match open_with_redirects(
        wide.as_ptr(),
        desired_access,
        share_mode,
        security,
        creation_disposition,
        flags,
        template,
    ) {
        Some(handle) => handle,
        None => passthrough(filename),
    }
}

/// Shared redirect core for both CreateFile entry points. Returns
/// Some(handle) when the open was served through a redirect rule, None
/// when no rule matched — the caller then invokes its OWN real entry
/// point with its ORIGINAL argument form (A stays ANSI).
unsafe fn open_with_redirects(
    filename: *const u16,
    desired_access: u32,
    share_mode: u32,
    security: *mut core::ffi::c_void,
    creation_disposition: u32,
    flags: u32,
    template: isize,
) -> Option<isize> {
    type RealW =
        unsafe extern "system" fn(*const u16, u32, u32, *mut core::ffi::c_void, u32, u32, isize) -> isize;
    let real: RealW = crate::events::real_create_file_w()?;
    let cfg = config();

    if let Some(redirect) = cfg.and_then(|c| c.redirect_xdf.clone()) {
        if !filename.is_null() {
            let mut len = 0usize;
            while *filename.add(len) != 0 {
                len += 1;
            }
            let path = core::slice::from_raw_parts(filename, len);
            // M7: the whole live-service config (gate keys, gates, server
            // list) — LuaScripts.xdf. M8: the FPX SDK account surface —
            // fpx_config_pc (b64(DES-ECB(json)), endpoints rewritten to
            // Serviimo by tools/fpxconf.py) + fpx_md5sums (hashes for the
            // SDK's own file check, regenerated for our config).
            let sub = if wide_ends_with(path, b"lua\\luascripts.xdf") {
                Some((redirect.replace('/', "\\"), "LuaScripts.xdf"))
            } else if wide_ends_with(path, b"lua\\luascripts.xdt") {
                // The size/MD5 manifest for the XDF — MUST ship with the
                // substituted XDF or the Lua bootstrap aborts with
                // "LuaData Corrupted: badSize" (CMDataLen check, live
                // 2026-09-28). xdfconf.py regenerates it in lockstep.
                Some(("AniiModLoader\\Serviimo\\LuaScripts.xdt".into(), "LuaScripts.xdt"))
            } else if wide_ends_with(path, b"fpx_config_pc") {
                Some(("AniiModLoader\\Serviimo\\fpx_config_pc".into(), "fpx_config_pc"))
            } else if wide_ends_with(path, b"fpx_md5sums") {
                Some(("AniiModLoader\\Serviimo\\fpx_md5sums".into(), "fpx_md5sums"))
            } else {
                None
            };
            // M10 profile isolation (alt-save) — mod-owned, see
            // [profile_key]. Remaps the vanilla persistent-data tree into
            // the AniiSignal profile dir, keeping the per-user tail
            // (`client_cache\...`, `Player.log`) intact. No AniiSignal
            // config → no remap (vanilla path, even under the loader).
            let mut profile_redirect: Option<(Vec<u16>, &'static str)> = match (&sub, profile_key()) {
                (None, Some(key)) => local_low_tail_start(path).map(|tail_at| {
                    let tail = &path[tail_at..];
                    let mut new_path: Vec<u16> = {
                        let exe_dir = crate::sys::exe_dir();
                        let mut p: Vec<u16> =
                            exe_dir.as_os_str().encode_wide().collect();
                        p.push(b'\\' as u16);
                        p.extend(
                            format!("AniiModLoader\\ServiimoProfile\\{key}\\")
                                .encode_utf16(),
                        );
                        p
                    };
                    new_path.extend_from_slice(tail);
                    (new_path, "profile")
                }),
                _ => None,
            };
            if let Some((mut new_path, label)) = profile_redirect {
                // Unity opens profile files whose parents do not exist on
                // a fresh profile (CREATE_ALWAYS fails without the dirs);
                // create them ourselves before the real call.
                let os_str: std::ffi::OsString =
                    std::os::windows::ffi::OsStringExt::from_wide(&new_path);
                let as_path = std::path::PathBuf::from(os_str);
                if let Some(parent) = as_path.parent() {
                    let _ = std::fs::create_dir_all(parent);
                }
                let n = REDIRECT_HITS_PER[4].fetch_add(1, Ordering::Relaxed);
                if n == 0 {
                    let shown: String = String::from_utf16_lossy(&new_path);
                    log(&format!(
                        "M10: profile isolated → ServiimoProfile ({} bytes path, first hit)",
                        shown.rsplit(['\\', '/']).next().unwrap_or("?")
                    ));
                    log(&format!("M10: profile root sample: {}", &shown[..shown.len().min(140)]));
                } else if n == 1000 {
                    log(&format!("M10: profile redirect hit #{n} (ongoing)"));
                }
                new_path.push(0);
                return Some(real(
                    new_path.as_ptr(),
                    desired_access,
                    share_mode,
                    security,
                    creation_disposition,
                    flags,
                    template,
                ));
            }
            if let Some((rel, label)) = sub {
                // absolute redirect path built from the game dir
                let mut new_path: Vec<u16> = {
                    use std::os::windows::ffi::OsStrExt;
                    let exe_dir = crate::sys::exe_dir();
                    let mut p: Vec<u16> = exe_dir.as_os_str().encode_wide().collect();
                    p.push(b'\\' as u16);
                    p.extend(rel.encode_utf16());
                    p
                };
                new_path.push(0);
                const INVALID_FILE_ATTRIBUTES: u32 = 0xFFFF_FFFF;
                if unsafe { GetFileAttributesW(new_path.as_ptr()) } == INVALID_FILE_ATTRIBUTES {
                    return None;
                }
                // log each label's FIRST hit (its own counter — a shared
                // one hides the later redirects: xdt logs, xdf+fpx stay
                // silent, and the boot log under-reports what's armed)
                let slot = match label {
                    "LuaScripts.xdf" => 0,
                    "LuaScripts.xdt" => 1,
                    "fpx_config_pc" => 2,
                    _ => 3,
                };
                let n = REDIRECT_HITS_PER[slot].fetch_add(1, Ordering::Relaxed);
                if n == 0 {
                    log(&format!("M7: {label} open redirected to Serviimo file"));
                } else if n == 1000 {
                    log(&format!("M7: {label} redirect hit #{n} (ongoing)"));
                }
                return Some(real(
                    new_path.as_ptr(),
                    desired_access,
                    share_mode,
                    security,
                    creation_disposition,
                    flags,
                    template,
                ));
            }
        }
    }
    None
}

/// getaddrinfo detour: refuse blocked domain suffixes.
pub unsafe extern "system" fn getaddrinfo_detour(
    node: *const u8,
    service: *const u8,
    hints: *const core::ffi::c_void,
    out: *mut *mut core::ffi::c_void,
) -> i32 {
    if let Some(real) = crate::events::real_getaddrinfo() {
        if !node.is_null() {
            if is_blocked_name_ascii(node) {
                let n = BLOCK_HITS.fetch_add(1, Ordering::Relaxed);
                if n == 0 {
                    log("M7: vanilla domain resolution BLOCKED");
                }
                return 11001; // WSAHOST_NOT_FOUND
            }
            return real(node, service, hints, out);
        }
        return real(node, service, hints, out);
    }
    11001
}

/// GetAddrInfoW detour (wide variant).
pub unsafe extern "system" fn getaddrinfo_w_detour(
    node: *const u16,
    service: *const u16,
    hints: *const core::ffi::c_void,
    out: *mut *mut core::ffi::c_void,
) -> i32 {
    if let Some(real) = crate::events::real_getaddrinfo_w() {
        if !node.is_null() {
            let mut len = 0usize;
            while *node.add(len) != 0 {
                len += 1;
            }
            let name = core::slice::from_raw_parts(node, len);
            if is_blocked_name_wide(name) {
                let n = BLOCK_HITS.fetch_add(1, Ordering::Relaxed);
                if n == 0 {
                    log("M7: vanilla domain resolution BLOCKED (wide)");
                }
                return 11001;
            }
            return real(node, service, hints, out);
        }
        return real(node, service, hints, out);
    }
    11001
}

fn is_blocked_name_ascii(node: *const u8) -> bool {
    unsafe {
        let mut len = 0usize;
        while *node.add(len) != 0 {
            len += 1;
        }
        let name = core::slice::from_raw_parts(node, len);
        is_blocked_name(name.iter().map(|b| *b).collect())
    }
}

fn is_blocked_name_wide(name: &[u16]) -> bool {
    is_blocked_name(name.iter().map(|w| (w & 0xFF) as u8).collect())
}

fn is_blocked_name(bytes: Vec<u8>) -> bool {
    let Some(cfg) = config() else { return false };
    let lower: Vec<u8> = bytes.iter().map(|b| b.to_ascii_lowercase()).collect();
    cfg.blocked_domains.iter().any(|d| {
        let d = d.to_ascii_lowercase().into_bytes();
        lower.len() >= d.len() && lower[lower.len() - d.len()..] == d[..]
            || lower.len() > d.len()
                && lower.ends_with(&d)
                && lower[lower.len() - d.len() - 1] == b'.'
                || lower == d
    })
}
